<?php declare(strict_types=1);namespace StudPulse\Bars;use DOMElement;use DOMXPath;use StudPulse\Config;final class BarsJournal{public const GROUPS='/bars_web/SG/StudyGroup/ListStudyGroup';public const GROUP='/bars_web/SG/StudyGroup/EditStudyGroup';public const JOURNALS='/bars_web/SG/TrainingJournal/ListStudyGroup__TrainingJournals';public const STUDENTS='/bars_web/SG/Student/ListStudyGroup__Students';public const JOURNAL='/bars_web/SG/TrainingJournal/EditTrainingJournal';public static function group(DOMXPath$page,string$code):?string{$matches=[];foreach($page->query('//tr[td]')as$row){$cells=$page->query('./td',$row);$sameGroup=false;foreach($cells as$cell){if(self::groupKey(BarsHtml::text($cell))===self::groupKey($code)){$sameGroup=true;break;}}if(!$sameGroup){continue;}foreach($page->query('.//a[@href]',$row)as$link){$pattern='/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/iD';$id=self::id($link->getAttribute('href'),self::GROUP,'sgid',$pattern)??self::id($link->getAttribute('href'),self::JOURNALS,'sgid',$pattern);if($id!==null){$matches[$id]=$id;}}}return count($matches)===1?reset($matches):null;}public static function responsibleRole(DOMXPath$page,string$login,string$code):?string{$login=strtolower($login);$headman=self::personKey(self::field($page,'Староста'),$code);foreach($page->query('//table')as$table){if(!self::responsibleTable($page,$table)){continue;}$columns=[];foreach($page->query('./thead/tr | ./tbody/tr | ./tr',$table)as$row){$cells=array_map(BarsHtml::text(...),iterator_to_array($page->query('./th | ./td',$row)));if(!$columns){$headers=array_map(mb_strtolower(...),$cells);$keys=['логин','фамилия','имя','отчество'];if(!array_diff($keys,$headers)){$columns=array_map(static fn(string$key):int=>array_search($key,$headers,true),$keys);}continue;}[$account,$last,$first,$middle]=$columns;$value=strtolower($cells[$account]??'');if($value!==$login&&$value!=='public\\'.$login){continue;}$name=self::personKey(implode(' ',[$cells[$last]??'',$cells[$first]??'',$cells[$middle]??'']),$code);return$headman!==''&&$name===$headman?'headman':'deputy';}}return null;}private static function responsibleTable(DOMXPath$page,DOMElement$table):bool{for($node=$table,$level=0;$node instanceof DOMElement&&$level<4;$node=$node->parentNode,++$level){if($node!==$table&&$page->query('.//table',$node)->length!==1){break;}if(str_contains(mb_strtolower(BarsHtml::text($node)),'ответственные за учебный журнал')){return true;}if($level===0&&$node->previousElementSibling&&mb_strtolower(BarsHtml::text($node->previousElementSibling))==='ответственные за учебный журнал'){return true;}}return false;}private static function field(DOMXPath$page,string$name):string{foreach($page->query('//label | //dt | //th | //span | //div')as$label){if(rtrim(BarsHtml::text($label),':')!==$name){continue;}$id=$label->getAttribute('for');$control=$id!==''?$page->document->getElementById($id):null;foreach([$control,$label->nextElementSibling,$label->parentNode?->nextElementSibling]as$node){if(!$node instanceof DOMElement){continue;}$input=$node->tagName==='input'?$node:$page->query('.//input[not(@type="hidden") and @value]',$node)->item(0);$value=$input?trim($input->getAttribute('value')):BarsHtml::text($node);if($value!==''){return$value;}}}return'';}private static function personKey(string$name,string$code):string{$name=preg_replace('/\s*\('.preg_quote($code,'/').'\)\s*$/uiD','',$name);return str_replace('ё','е',mb_strtolower(trim(preg_replace('/\s+/u',' ',$name))));}public static function headmanName(DOMXPath$page,string$code):string{$name=self::field($page,'Староста');return trim(preg_replace('/\s*\('.preg_quote($code,'/').'\)\s*$/uiD','',$name));}public static function rememberHeadman(string$code,array$period,string$name):void{$path=self::headmanPath($code,$period);if(!is_dir(dirname($path))){@mkdir(dirname($path),0700,true);}@file_put_contents($path,$name,LOCK_EX);}public static function cachedHeadman(string$code):?string{$path=self::headmanPath($code,self::currentP